-- R-058/R-081/R-082/R-121. Native AE fixed-input render and actual-video adoption.
-- All previously applied migrations remain immutable. Files precede transactional rows.
ALTER TABLE ae_render_jobs ADD COLUMN input_version bigint NOT NULL DEFAULT 1 CHECK(input_version>0);
ALTER TABLE ae_media_adoptions ADD COLUMN native_synthetic bigint NOT NULL DEFAULT 0 CHECK(native_synthetic IN(0,1));
CREATE TABLE _dg_native_ae_render_inputs(job_id text NOT NULL REFERENCES ae_render_jobs(id),generation bigint NOT NULL CHECK(generation>0),input_snapshot text NOT NULL,input_hash text NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'),created_at text NOT NULL,PRIMARY KEY(job_id,generation));
CREATE TABLE _dg_native_ae_render_receipts(job_id text PRIMARY KEY REFERENCES ae_render_jobs(id),lease_token text NOT NULL,input_hash text NOT NULL,receipt text NOT NULL,receipt_hash text NOT NULL CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),created_at text NOT NULL);
CREATE TABLE _dg_native_ae_render_leases(job_id text PRIMARY KEY REFERENCES ae_render_jobs(id),token text NOT NULL,lease_until text NOT NULL);
CREATE TABLE _dg_native_ae_media_inputs(adoption_id text PRIMARY KEY REFERENCES ae_media_adoptions(id),input_snapshot text NOT NULL,input_hash text NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'),created_at text NOT NULL);
CREATE TABLE _dg_native_ae_media_receipts(adoption_id text PRIMARY KEY REFERENCES ae_media_adoptions(id),lease_token text NOT NULL,input_hash text NOT NULL,receipt text NOT NULL,receipt_hash text NOT NULL CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),created_at text NOT NULL);
CREATE TABLE _dg_native_ae_media_leases(adoption_id text PRIMARY KEY REFERENCES ae_media_adoptions(id),token text NOT NULL,lease_until text NOT NULL);
CREATE UNIQUE INDEX native_ae_artifact_kind ON ae_render_artifacts(job_id,kind);
ALTER TABLE ae_batches ADD CONSTRAINT native_ae_batch_shape CHECK(version>0 AND environment='mock' AND app_env IN('development','sandbox') AND mode IN('contract_test','local_aerender') AND kind IN('mp4','mov_alpha'));
ALTER TABLE ae_render_jobs ADD CONSTRAINT native_ae_job_shape CHECK(version>0 AND attempts BETWEEN 0 AND 3 AND(status<>'rendering' OR(lease_token IS NOT NULL AND lease_until IS NOT NULL)));
ALTER TABLE ae_media_adoptions ADD CONSTRAINT native_ae_media_shape CHECK(version>0 AND control_version>0 AND attempts BETWEEN 0 AND 3 AND environment='mock' AND app_env IN('development','sandbox') AND(status<>'processing' OR(lease_token IS NOT NULL AND lease_until IS NOT NULL)));
ALTER TABLE _dg_native_asset_origins DROP CONSTRAINT native_asset_source_kind;
ALTER TABLE _dg_native_asset_origins ADD CONSTRAINT native_asset_source_kind CHECK(source_kind IN('private_upload','package_import','video_upload','system_speech','media_processing','recording','ae_media'));
CREATE FUNCTION dg_native_ae_render_binding() RETURNS trigger LANGUAGE plpgsql AS $dg$
DECLARE target text:=COALESCE(to_jsonb(NEW)->>'job_id',to_jsonb(NEW)->>'id');j ae_render_jobs%ROWTYPE;b ae_batches%ROWTYPE;i _dg_native_ae_render_inputs%ROWTYPE;v jsonb;
BEGIN
 SELECT * INTO j FROM ae_render_jobs WHERE id=target;SELECT * INTO b FROM ae_batches WHERE id=j.batch_id;SELECT * INTO i FROM _dg_native_ae_render_inputs WHERE job_id=target AND generation=j.input_version;v:=i.input_snapshot::jsonb;
 IF j.id IS NULL OR i.job_id IS NULL OR v-ARRAY['references','execution','valid'] IS DISTINCT FROM jsonb_build_object('batchId',b.id,'jobId',j.id,'generation',j.input_version,'tenantId',b.tenant_id,'workspaceId',b.workspace_id,'actorId',j.actor_id,'templateId',b.template_id,'templateVersion',b.template_version,'manifestSHA256',b.manifest_sha256,'runtimeId',b.runtime_id,'kind',b.kind,'parameters',j.parameters::jsonb,'sourceHash',j.source_hash) OR NOT COALESCE(jsonb_typeof(v->'references')='array' AND jsonb_typeof(v->'execution')='object' AND jsonb_typeof(v->'valid')='boolean',false) OR NOT EXISTS(SELECT 1 FROM ae_templates t JOIN ae_template_versions h ON h.template_id=t.id AND h.version=b.template_version WHERE t.id=b.template_id AND t.tenant_id=b.tenant_id AND t.workspace_id=b.workspace_id AND t.app_env=b.app_env AND h.manifest_sha256=b.manifest_sha256 AND h.manifest::jsonb=b.manifest::jsonb) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE render requires exact immutable versioned input and template history';END IF;RETURN NULL;
END;$dg$;
CREATE CONSTRAINT TRIGGER native_ae_render_binding AFTER INSERT OR UPDATE ON ae_render_jobs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_ae_render_binding();
CREATE CONSTRAINT TRIGGER native_ae_render_input_binding AFTER INSERT ON _dg_native_ae_render_inputs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_ae_render_binding();
CREATE FUNCTION dg_native_ae_render_guard() RETURNS trigger LANGUAGE plpgsql AS $dg$
BEGIN
 IF TG_OP='INSERT' THEN IF NEW.status NOT IN('queued','failed') OR NEW.version<>1 OR NEW.input_version<>1 OR NEW.attempts<>(CASE WHEN NEW.status='failed' THEN 1 ELSE 0 END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='New native AE rows start queued or explicitly invalid';END IF;
 ELSE
  IF OLD.status IN('succeeded','cancelled') OR NEW.version<OLD.version OR NEW.version>OLD.version+1 OR to_jsonb(NEW)-ARRAY['name','parameters','actor_id','source_hash','input_version','status','stage','version','attempts','lease_token','lease_until','error_code','error_message','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['name','parameters','actor_id','source_hash','input_version','status','stage','version','attempts','lease_token','lease_until','error_code','error_message','updated_at'] OR(NEW.version=OLD.version AND to_jsonb(NEW)-ARRAY['lease_until','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['lease_until','updated_at']) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native AE job identity, terminal state and versions are fenced';END IF;
  IF (NEW.input_version<>OLD.input_version OR NEW.parameters::jsonb<>OLD.parameters::jsonb OR NEW.actor_id IS DISTINCT FROM OLD.actor_id OR NEW.source_hash IS DISTINCT FROM OLD.source_hash OR NEW.name<>OLD.name) AND NOT(OLD.status='failed' AND NEW.status='queued' AND NEW.input_version=OLD.input_version+1 AND NEW.version=OLD.version+1 AND NEW.attempts=OLD.attempts) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE corrected retry requires a new immutable input generation';END IF;
  IF NEW.status='succeeded' AND(NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND session_user=worker_role) OR NOT EXISTS(SELECT 1 FROM _dg_native_ae_render_receipts WHERE job_id=NEW.id AND lease_token=OLD.lease_token)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE success requires controlled worker completion';END IF;
 END IF;RETURN NEW;
END;$dg$;
CREATE TRIGGER native_ae_render_guard BEFORE INSERT OR UPDATE ON ae_render_jobs FOR EACH ROW EXECUTE FUNCTION dg_native_ae_render_guard();
CREATE FUNCTION dg_native_ae_media_binding() RETURNS trigger LANGUAGE plpgsql AS $dg$
DECLARE target text:=COALESCE(to_jsonb(NEW)->>'adoption_id',to_jsonb(NEW)->>'id');r ae_media_adoptions%ROWTYPE;i _dg_native_ae_media_inputs%ROWTYPE;v jsonb;
BEGIN
 SELECT * INTO r FROM ae_media_adoptions WHERE id=target;SELECT * INTO i FROM _dg_native_ae_media_inputs WHERE adoption_id=target;v:=i.input_snapshot::jsonb;
 IF r.id IS NULL OR i.adoption_id IS NULL OR v-'execution' IS DISTINCT FROM jsonb_build_object('adoptionId',r.id,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'actorId',r.actor_id,'artifactId',r.artifact_id,'batchId',r.batch_id,'jobId',r.job_id,'name',r.name,'rightsNote',r.rights_note,'expiresAt',r.expires_at,'snapshot',r.snapshot::jsonb,'snapshotHash',r.snapshot_hash,'planHash',r.plan_hash,'synthetic',r.native_synthetic=1) OR NOT COALESCE(jsonb_typeof(v->'execution')='object',false) OR NOT EXISTS(SELECT 1 FROM ae_render_artifacts a JOIN ae_render_jobs j ON j.id=a.job_id JOIN ae_batches b ON b.id=j.batch_id WHERE a.id=r.artifact_id AND a.kind='video' AND j.id=r.job_id AND b.id=r.batch_id AND b.tenant_id=r.tenant_id AND b.workspace_id=r.workspace_id AND b.app_env=r.app_env AND j.status='succeeded' AND j.version=(r.snapshot::jsonb->>'jobVersion')::bigint AND a.sha256=r.snapshot::jsonb->'video'->>'sha256' AND a.size=(r.snapshot::jsonb->'video'->>'size')::bigint AND(b.mode<>'contract_test' OR r.native_synthetic=1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE adoption needs exact immutable actual render origin';END IF;RETURN NULL;
END;$dg$;
CREATE CONSTRAINT TRIGGER native_ae_media_binding AFTER INSERT OR UPDATE ON ae_media_adoptions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_ae_media_binding();
CREATE CONSTRAINT TRIGGER native_ae_media_input_binding AFTER INSERT ON _dg_native_ae_media_inputs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_ae_media_binding();
CREATE FUNCTION dg_native_ae_media_guard() RETURNS trigger LANGUAGE plpgsql AS $dg$
BEGIN
 IF TG_OP='INSERT' THEN IF NEW.status<>'queued' OR NEW.attempts<>0 OR NEW.version<>1 OR NEW.control_version<>1 OR NEW.asset_id IS NOT NULL OR NEW.project_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native AE adoption starts queued without output';END IF;
 ELSE
  IF NEW.native_synthetic<>OLD.native_synthetic OR NEW.version<>OLD.version+1 OR NEW.control_version<OLD.control_version OR NEW.control_version>OLD.control_version+1 OR(OLD.status='succeeded' AND NEW.status<>'withdrawn') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE adoption state, synthetic provenance and versions are fenced';END IF;
  IF NEW.status='succeeded' AND(NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND session_user=worker_role) OR NOT EXISTS(SELECT 1 FROM _dg_native_ae_media_receipts c WHERE c.adoption_id=NEW.id AND c.lease_token=OLD.lease_token AND c.receipt::jsonb->>'assetId'=NEW.asset_id AND c.receipt::jsonb->>'projectId'=NEW.project_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE asset/project success needs controlled completion';END IF;
 END IF;RETURN NEW;
END;$dg$;
CREATE TRIGGER native_ae_media_guard BEFORE INSERT OR UPDATE ON ae_media_adoptions FOR EACH ROW EXECUTE FUNCTION dg_native_ae_media_guard();
DO $dg$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['_dg_native_ae_render_inputs','_dg_native_ae_render_receipts','_dg_native_ae_media_inputs','_dg_native_ae_media_receipts','ae_render_artifacts'] LOOP EXECUTE format('CREATE TRIGGER native_ae_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_append_only()',t);END LOOP;END;$dg$;
CREATE FUNCTION dg_native_ae_refresh_batch(target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE next_status text;BEGIN
 IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control c JOIN ae_batches b ON b.app_env=c.app_env WHERE c.id=1 AND c.status='validation_only' AND session_user IN(c.api_role,c.worker_role) AND b.id=target) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Native runtime batch only';END IF;
 SELECT CASE WHEN count(*) FILTER(WHERE status IN('queued','rendering'))>0 THEN 'running' WHEN count(*) FILTER(WHERE status IN('failed','cancelled'))>0 THEN 'completed_with_errors' ELSE 'completed' END INTO next_status FROM ae_render_jobs WHERE batch_id=target;
 UPDATE ae_batches SET status=next_status,version=version+1,updated_at=dg_utc_now() WHERE id=target AND status<>'cancelled' AND status<>next_status;
END;$dg$;
CREATE FUNCTION dg_native_ae_render_valid(target text,token text,completed boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE app text;j ae_render_jobs%ROWTYPE;b ae_batches%ROWTYPE;v jsonb;
BEGIN
 SELECT app_env INTO app FROM _dg_native_runtime_control WHERE id=1 AND status='validation_only' AND session_user=worker_role;IF app IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker validates native AE render';END IF;
 SELECT * INTO j FROM ae_render_jobs WHERE id=target;SELECT * INTO b FROM ae_batches WHERE id=j.batch_id;SELECT input_snapshot::jsonb INTO v FROM _dg_native_ae_render_inputs WHERE job_id=j.id AND generation=j.input_version;
 IF j.id IS NULL OR b.app_env<>app OR b.environment<>'mock' OR v IS NULL OR NOT COALESCE((v->>'valid')::boolean,false) OR NOT EXISTS(SELECT 1 FROM memberships WHERE user_id=j.actor_id AND tenant_id=b.tenant_id AND role IN('admin','editor') AND workspace_ids::jsonb ? b.workspace_id) OR(b.manifest::jsonb->'license'->>'expiresAt' IS NOT NULL AND b.manifest::jsonb->'license'->>'expiresAt'<=dg_utc_now()) OR NOT EXISTS(SELECT 1 FROM _dg_native_ae_render_leases l WHERE l.job_id=j.id AND l.token=dg_native_ae_render_valid.token AND l.lease_until>dg_utc_now()) OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'references') r LEFT JOIN assets a ON a.id=r->>'id' LEFT JOIN uploads u ON u.id=a.upload_id WHERE a.id IS NULL OR a.tenant_id<>b.tenant_id OR a.workspace_id<>b.workspace_id OR a.archived<>0 OR a.version<>(r->>'version')::bigint OR u.sha256<>r->>'sha256' OR u.size<>(r->>'size')::bigint OR a.expires_at IS DISTINCT FROM r->>'expiresAt' OR a.expires_at<=dg_utc_now()) THEN RETURN false;END IF;
 RETURN(NOT completed AND b.status='running' AND j.status='rendering' AND j.lease_token=token AND j.lease_until>dg_utc_now()) OR(completed AND j.status='succeeded' AND EXISTS(SELECT 1 FROM _dg_native_ae_render_receipts c WHERE c.job_id=j.id AND c.lease_token=dg_native_ae_render_valid.token));
END;$dg$;
CREATE FUNCTION dg_native_ae_render_claim(capacity integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE app text;j ae_render_jobs%ROWTYPE;token text:=gen_random_uuid()::text;until_at text;bid text;
BEGIN
 SELECT app_env INTO app FROM _dg_native_runtime_control WHERE id=1 AND status='validation_only' AND session_user=worker_role;IF app IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker claims native AE renders';END IF;
 IF capacity IS NULL OR capacity NOT BETWEEN 1 AND 2 OR NOT pg_try_advisory_xact_lock(hashtextextended('native-ae-render-capacity',0)) THEN RETURN NULL;END IF;DELETE FROM _dg_native_ae_render_leases WHERE lease_until<=dg_utc_now();
 FOR bid IN SELECT b.id FROM ae_batches b WHERE b.app_env=app AND b.status='running' AND EXISTS(SELECT 1 FROM ae_render_jobs j WHERE j.batch_id=b.id AND j.status='rendering' AND j.lease_until<=dg_utc_now() AND j.attempts>=3) FOR UPDATE OF b SKIP LOCKED LOOP
  UPDATE ae_render_attempts a SET status='interrupted',error_message='原租约中断且恢复次数已用完。',finished_at=dg_utc_now() FROM ae_render_jobs x WHERE a.job_id=x.id AND x.batch_id=bid AND x.status='rendering' AND x.lease_until<=dg_utc_now() AND x.attempts>=3 AND a.status='rendering';
  UPDATE ae_render_jobs SET status='failed',stage='finished',version=version+1,lease_token=NULL,lease_until=NULL,error_code='AE_RECOVERY_LIMIT',error_message='三次执行已用完，请保留记录并新建批次。',updated_at=dg_utc_now() WHERE batch_id=bid AND status='rendering' AND lease_until<=dg_utc_now() AND attempts>=3;PERFORM dg_native_ae_refresh_batch(bid);
 END LOOP;
 IF(SELECT count(*) FROM _dg_native_ae_render_leases)>=capacity THEN RETURN NULL;END IF;
 SELECT x.* INTO j FROM ae_render_jobs x JOIN ae_batches b ON b.id=x.batch_id WHERE b.app_env=app AND b.environment='mock' AND b.status='running' AND x.attempts<3 AND(x.status='queued' OR x.status='rendering' AND x.lease_until<=dg_utc_now()) AND NOT EXISTS(SELECT 1 FROM _dg_native_ae_render_leases WHERE job_id=x.id) ORDER BY x.created_at,x.position,x.id LIMIT 1 FOR UPDATE OF b,x SKIP LOCKED;IF j.id IS NULL THEN RETURN NULL;END IF;
 UPDATE ae_render_attempts SET status='interrupted',error_message='原租约中断，使用原固定输入和新目录自然恢复。',finished_at=dg_utc_now() WHERE job_id=j.id AND status='rendering';until_at:=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 UPDATE ae_render_jobs SET status='rendering',stage='preparing',version=version+1,attempts=attempts+1,lease_token=token,lease_until=until_at,error_code=NULL,error_message=NULL,updated_at=dg_utc_now() WHERE id=j.id RETURNING * INTO j;
 INSERT INTO ae_render_attempts VALUES(j.id,j.attempts,'rendering',j.parameters,NULL,dg_utc_now(),NULL,j.actor_id);INSERT INTO _dg_native_ae_render_leases VALUES(j.id,token,until_at);RETURN to_jsonb(j);
END;$dg$;
CREATE FUNCTION dg_native_ae_render_hold(target text,token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND session_user=worker_role) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker holds AE execution';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('native-ae-render-capacity',0));UPDATE _dg_native_ae_render_leases SET lease_until=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') WHERE job_id=target AND _dg_native_ae_render_leases.token=dg_native_ae_render_hold.token AND lease_until>dg_utc_now();RETURN FOUND;END;$dg$;
CREATE FUNCTION dg_native_ae_render_release(target text,token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND session_user=worker_role) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker releases AE execution';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('native-ae-render-capacity',0));DELETE FROM _dg_native_ae_render_leases WHERE job_id=target AND _dg_native_ae_render_leases.token=dg_native_ae_render_release.token;RETURN FOUND;END;$dg$;
CREATE FUNCTION dg_native_ae_render_renew(target text,token text,stage_value text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT dg_native_ae_render_valid(target,token,false) OR stage_value NOT IN('preparing','rendering','validating') THEN RETURN false;END IF;UPDATE ae_render_jobs SET stage=stage_value,version=version+CASE WHEN stage<>stage_value THEN 1 ELSE 0 END,lease_until=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),updated_at=dg_utc_now() WHERE id=target AND status='rendering' AND lease_token=token AND lease_until>dg_utc_now();RETURN FOUND;END;$dg$;
CREATE FUNCTION dg_native_ae_render_fail(target text,token text,code_value text,message_value text,stopped boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE bid text;BEGIN
 IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND status='validation_only' AND session_user=worker_role) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker settles AE render failure';END IF;
 UPDATE ae_render_jobs SET status=CASE WHEN stopped THEN 'queued' ELSE 'failed' END,stage=CASE WHEN stopped THEN 'queued' ELSE 'finished' END,attempts=attempts-CASE WHEN stopped THEN 1 ELSE 0 END,version=version+1,lease_token=NULL,lease_until=NULL,error_code=CASE WHEN stopped THEN NULL ELSE code_value END,error_message=CASE WHEN stopped THEN NULL ELSE message_value END,updated_at=dg_utc_now() WHERE id=target AND status='rendering' AND lease_token=token AND lease_until>dg_utc_now() RETURNING batch_id INTO bid;IF bid IS NULL THEN RETURN false;END IF;
 IF stopped THEN DELETE FROM ae_render_attempts WHERE job_id=target AND status='rendering';ELSE UPDATE ae_render_attempts SET status='failed',error_message=message_value,finished_at=dg_utc_now() WHERE job_id=target AND status='rendering';END IF;PERFORM dg_native_ae_refresh_batch(bid);RETURN true;
END;$dg$;
CREATE FUNCTION dg_native_commit_ae_render(target text,token text,actual_input text,receipt_text text,receipt_digest text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j ae_render_jobs%ROWTYPE;b ae_batches%ROWTYPE;i _dg_native_ae_render_inputs%ROWTYPE;v jsonb:=receipt_text::jsonb;a jsonb;o jsonb;
BEGIN
 SELECT * INTO j FROM ae_render_jobs WHERE id=target FOR UPDATE;SELECT * INTO b FROM ae_batches WHERE id=j.batch_id;SELECT * INTO i FROM _dg_native_ae_render_inputs WHERE job_id=j.id AND generation=j.input_version;
 IF NOT dg_native_ae_render_valid(target,token,false) OR i.input_hash IS DISTINCT FROM actual_input OR NOT COALESCE(receipt_digest ~ '^[a-f0-9]{64}$',false) OR v->>'mode' IS DISTINCT FROM b.mode OR v->>'runtimeId' IS DISTINCT FROM b.runtime_id OR v->>'manifestSHA256' IS DISTINCT FROM b.manifest_sha256 OR v->>'sourceHash' IS DISTINCT FROM j.source_hash OR v->'execution' IS DISTINCT FROM i.input_snapshot::jsonb->'execution' OR NOT COALESCE(jsonb_typeof(v->'artifacts')='array' AND jsonb_array_length(v->'artifacts')=2,false) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'artifacts') x WHERE x->>'kind'='video') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'artifacts') x WHERE x->>'kind'='receipt') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE render completion needs current lease, original input and two exact artifacts';END IF;
 FOR a IN SELECT * FROM jsonb_array_elements(v->'artifacts') LOOP o:=a->'object';IF NOT COALESCE(a->>'id' ~ '^[a-f0-9-]{36}$' AND o->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND o->>'sha256' ~ '^[a-f0-9]{64}$' AND(o->>'size')::bigint BETWEEN 1 AND CASE WHEN a->>'kind'='video' THEN 34359738368 ELSE 65536 END AND a->>'mediaType'=CASE WHEN a->>'kind'='receipt' THEN 'application/json' WHEN b.kind='mp4' THEN 'video/mp4' ELSE 'video/quicktime' END,false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE output file receipt is incomplete or exceeds its bound';END IF;
  INSERT INTO ae_render_artifacts VALUES(a->>'id',j.id,a->>'kind',a->>'name',a->>'mediaType',o->>'storage_key',(o->>'size')::bigint,o->>'sha256',dg_utc_now());END LOOP;
 INSERT INTO _dg_native_ae_render_receipts VALUES(j.id,token,i.input_hash,receipt_text,receipt_digest,dg_utc_now());UPDATE ae_render_jobs SET status='succeeded',stage='finished',version=version+1,lease_token=NULL,lease_until=NULL,error_code=NULL,error_message=NULL,updated_at=dg_utc_now() WHERE id=j.id;UPDATE ae_render_attempts SET status='succeeded',finished_at=dg_utc_now() WHERE job_id=j.id AND attempt=j.attempts AND status='rendering';PERFORM dg_native_ae_refresh_batch(b.id);INSERT INTO audit_events VALUES(gen_random_uuid()::text,b.tenant_id,b.workspace_id,j.actor_id,'studio.ae.render.completed',j.id,'confirmed',token,dg_utc_now());RETURN j.id;
END;$dg$;
CREATE FUNCTION dg_native_ae_media_valid(target text,token text,completed boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE app text;r ae_media_adoptions%ROWTYPE;b ae_batches%ROWTYPE;
BEGIN
 SELECT app_env INTO app FROM _dg_native_runtime_control WHERE id=1 AND status='validation_only' AND session_user=worker_role;IF app IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker validates AE media';END IF;SELECT * INTO r FROM ae_media_adoptions WHERE id=target;SELECT * INTO b FROM ae_batches WHERE id=r.batch_id;
 IF r.id IS NULL OR r.app_env<>app OR r.environment<>'mock' OR r.withdrawn_at IS NOT NULL OR r.expires_at<=dg_utc_now() OR NOT EXISTS(SELECT 1 FROM memberships WHERE user_id=r.actor_id AND tenant_id=r.tenant_id AND role IN('admin','editor') AND workspace_ids::jsonb ? r.workspace_id) OR NOT EXISTS(SELECT 1 FROM _dg_native_ae_media_inputs WHERE adoption_id=r.id) OR NOT EXISTS(SELECT 1 FROM _dg_native_ae_media_leases l WHERE l.adoption_id=r.id AND l.token=dg_native_ae_media_valid.token AND l.lease_until>dg_utc_now()) OR(b.manifest::jsonb->'license'->>'expiresAt' IS NOT NULL AND b.manifest::jsonb->'license'->>'expiresAt'<=dg_utc_now()) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.snapshot::jsonb->'references') ref LEFT JOIN assets a ON a.id=ref->>'id' LEFT JOIN uploads u ON u.id=a.upload_id WHERE a.id IS NULL OR a.tenant_id<>r.tenant_id OR a.workspace_id<>r.workspace_id OR a.archived<>0 OR a.version<>(ref->>'version')::bigint OR u.sha256<>ref->>'sha256' OR u.size<>(ref->>'size')::bigint OR a.expires_at IS DISTINCT FROM ref->>'expiresAt' OR a.expires_at<=dg_utc_now()) THEN RETURN false;END IF;
 RETURN(NOT completed AND r.status='processing' AND r.lease_token=token AND r.lease_until>dg_utc_now()) OR(completed AND r.status='succeeded' AND EXISTS(SELECT 1 FROM _dg_native_ae_media_receipts c WHERE c.adoption_id=r.id AND c.lease_token=dg_native_ae_media_valid.token));
END;$dg$;
CREATE FUNCTION dg_native_ae_media_claim() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE app text;r ae_media_adoptions%ROWTYPE;token text:=gen_random_uuid()::text;until_at text;
BEGIN
 SELECT app_env INTO app FROM _dg_native_runtime_control WHERE id=1 AND status='validation_only' AND session_user=worker_role;IF app IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker claims AE media';END IF;IF NOT pg_try_advisory_xact_lock(hashtextextended('native-ae-media-capacity',0)) THEN RETURN NULL;END IF;DELETE FROM _dg_native_ae_media_leases WHERE lease_until<=dg_utc_now();
 UPDATE ae_media_attempts a SET status='interrupted',error_code='AE_MEDIA_RECOVERY_LIMIT',error_message='原租约中断且恢复次数已用完。',finished_at=dg_utc_now() FROM ae_media_adoptions j WHERE a.adoption_id=j.id AND a.status='processing' AND j.status='processing' AND j.lease_until<=dg_utc_now() AND j.attempts>=3 AND j.app_env=app;
 UPDATE ae_media_adoptions SET status='failed',stage='finished',version=version+1,control_version=control_version+1,lease_token=NULL,lease_until=NULL,error_code='AE_MEDIA_RECOVERY_LIMIT',error_message='三次检查已用完，请保留原记录。',updated_at=dg_utc_now() WHERE app_env=app AND status='processing' AND lease_until<=dg_utc_now() AND attempts>=3;
 IF(SELECT count(*) FROM _dg_native_ae_media_leases)>=2 THEN RETURN NULL;END IF;
 SELECT * INTO r FROM ae_media_adoptions j WHERE j.app_env=app AND j.environment='mock' AND j.attempts<3 AND(j.status='queued' OR j.status='processing' AND j.lease_until<=dg_utc_now()) AND NOT EXISTS(SELECT 1 FROM _dg_native_ae_media_leases WHERE adoption_id=j.id) ORDER BY j.created_at,j.id LIMIT 1 FOR UPDATE SKIP LOCKED;IF r.id IS NULL THEN RETURN NULL;END IF;
 UPDATE ae_media_attempts SET status='interrupted',error_code='AE_MEDIA_INTERRUPTED',error_message='原检查中断，使用原件和独立目录自然恢复。',finished_at=dg_utc_now() WHERE adoption_id=r.id AND status='processing';until_at:=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 UPDATE ae_media_adoptions SET status='processing',stage='copying',progress=0,version=version+1,attempts=attempts+1,lease_token=token,lease_until=until_at,error_code=NULL,error_message=NULL,updated_at=dg_utc_now() WHERE id=r.id RETURNING * INTO r;INSERT INTO ae_media_attempts VALUES(r.id,r.attempts,'processing',NULL,NULL,dg_utc_now(),NULL);INSERT INTO _dg_native_ae_media_leases VALUES(r.id,token,until_at);RETURN to_jsonb(r);
END;$dg$;
CREATE FUNCTION dg_native_ae_media_hold(target text,token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND session_user=worker_role) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker holds AE media';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('native-ae-media-capacity',0));UPDATE _dg_native_ae_media_leases SET lease_until=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') WHERE adoption_id=target AND _dg_native_ae_media_leases.token=dg_native_ae_media_hold.token AND lease_until>dg_utc_now();RETURN FOUND;END;$dg$;
CREATE FUNCTION dg_native_ae_media_release(target text,token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND session_user=worker_role) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker releases AE media';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('native-ae-media-capacity',0));DELETE FROM _dg_native_ae_media_leases WHERE adoption_id=target AND _dg_native_ae_media_leases.token=dg_native_ae_media_release.token;RETURN FOUND;END;$dg$;
CREATE FUNCTION dg_native_ae_media_renew(target text,token text,stage_value text,progress_value bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT dg_native_ae_media_valid(target,token,false) OR stage_value NOT IN('copying','inspecting','committing') OR progress_value NOT BETWEEN 0 AND 99 THEN RETURN false;END IF;UPDATE ae_media_adoptions SET stage=stage_value,progress=GREATEST(progress,progress_value),version=version+1,lease_until=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),updated_at=dg_utc_now() WHERE id=target AND status='processing' AND lease_token=token AND lease_until>dg_utc_now();RETURN FOUND;END;$dg$;
CREATE FUNCTION dg_native_ae_media_fail(target text,token text,code_value text,message_value text,stopped boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control WHERE id=1 AND status='validation_only' AND session_user=worker_role) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only worker settles AE media';END IF;
 UPDATE ae_media_adoptions SET status=CASE WHEN stopped THEN 'queued' ELSE 'failed' END,stage=CASE WHEN stopped THEN 'queued' ELSE 'finished' END,progress=CASE WHEN stopped THEN 0 ELSE progress END,attempts=attempts-CASE WHEN stopped THEN 1 ELSE 0 END,version=version+1,control_version=control_version+CASE WHEN stopped THEN 0 ELSE 1 END,lease_token=NULL,lease_until=NULL,error_code=CASE WHEN stopped THEN NULL ELSE code_value END,error_message=CASE WHEN stopped THEN NULL ELSE message_value END,updated_at=dg_utc_now() WHERE id=target AND status='processing' AND lease_token=token AND lease_until>dg_utc_now();IF NOT FOUND THEN RETURN false;END IF;
 IF stopped THEN DELETE FROM ae_media_attempts WHERE adoption_id=target AND status='processing';ELSE UPDATE ae_media_attempts SET status='failed',error_code=code_value,error_message=message_value,finished_at=dg_utc_now() WHERE adoption_id=target AND status='processing';END IF;RETURN true;
END;$dg$;
CREATE FUNCTION dg_native_commit_ae_media(target text,token text,actual_input text,receipt_text text,receipt_digest text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r ae_media_adoptions%ROWTYPE;i _dg_native_ae_media_inputs%ROWTYPE;v jsonb:=receipt_text::jsonb;o jsonb:=v->'object';poster jsonb:=v->'poster';proxy jsonb:=v->'preview';s jsonb:=v->'specs';origin jsonb;at_time text:=dg_utc_now();aid text:=v->>'assetId';uid text:=v->>'uploadId';pid text:=v->>'projectId';mime text:=v->>'mediaType';max_size bigint;
BEGIN
 SELECT * INTO r FROM ae_media_adoptions WHERE id=target FOR UPDATE;SELECT * INTO i FROM _dg_native_ae_media_inputs WHERE adoption_id=target;origin:=r.snapshot::jsonb;max_size:=CASE WHEN mime='video/quicktime' THEN 1073741824 ELSE 134217728 END;
 IF NOT dg_native_ae_media_valid(target,token,false) OR i.input_hash IS DISTINCT FROM actual_input OR NOT COALESCE(receipt_digest ~ '^[a-f0-9]{64}$' AND aid ~ '^[a-f0-9-]{36}$' AND uid ~ '^[a-f0-9-]{36}$' AND pid ~ '^[a-f0-9-]{36}$',false) OR v->>'originHash' IS DISTINCT FROM r.snapshot_hash OR v->>'expiresAt' IS DISTINCT FROM r.expires_at OR v->'synthetic' IS DISTINCT FROM to_jsonb(r.native_synthetic=1) OR v->'inspectionRuntime' IS DISTINCT FROM i.input_snapshot::jsonb->'execution' OR mime IS DISTINCT FROM origin->'video'->>'mediaType' OR o->>'sha256' IS DISTINCT FROM origin->'video'->>'sha256' OR o->>'size' IS DISTINCT FROM origin->'video'->>'size' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE media completion lost original bytes, fixed input or current lease';END IF;
 IF NOT COALESCE(o->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND o->>'sha256' ~ '^[a-f0-9]{64}$' AND(o->>'size')::bigint BETWEEN 1 AND max_size AND poster->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND poster->>'sha256' ~ '^[a-f0-9]{64}$' AND(poster->>'size')::bigint BETWEEN 1 AND 8388608 AND jsonb_typeof(s)='object' AND(s->>'width')::int=(origin->'manifest'->'output'->>'width')::int AND(s->>'height')::int=(origin->'manifest'->'output'->>'height')::int AND(s->>'durationMs')::numeric BETWEEN 100 AND 600000 AND(s->>'fps')::numeric BETWEEN 1 AND 60,false) OR NOT COALESCE(jsonb_typeof(v->'document')='object',false) OR(mime='video/quicktime' AND NOT COALESCE(proxy->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND proxy->>'sha256' ~ '^[a-f0-9]{64}$' AND(proxy->>'size')::bigint BETWEEN 1 AND 134217728,false)) OR(mime='video/mp4' AND proxy IS DISTINCT FROM 'null'::jsonb) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='AE media needs bounded actual file, poster, alpha proxy and video specs';END IF;
 IF(SELECT count(*) FROM studio_projects WHERE tenant_id=r.tenant_id AND workspace_id=r.workspace_id AND archived=0)>=200 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Workspace active project limit reached';END IF;
 INSERT INTO uploads VALUES(uid,r.tenant_id,r.workspace_id,r.actor_id,o->>'storage_key',o->>'sha256',(o->>'size')::bigint,mime,s::text,at_time);
 INSERT INTO assets(id,tenant_id,workspace_id,upload_id,name,category,synthetic,expires_at,created_at) VALUES(aid,r.tenant_id,r.workspace_id,uid,r.name,'reference',r.native_synthetic,r.expires_at,at_time);
 INSERT INTO _dg_native_asset_origins VALUES(aid,uid,r.tenant_id,r.workspace_id,o->>'sha256',(o->>'size')::bigint,'ae_media','mock',r.app_env,at_time);INSERT INTO video_sources VALUES(aid,poster->>'storage_key',poster->>'sha256',(poster->>'size')::bigint,at_time);
 IF mime='video/quicktime' THEN INSERT INTO alpha_video_previews VALUES(aid,proxy->>'storage_key',proxy->>'sha256',(proxy->>'size')::bigint,at_time);END IF;
 INSERT INTO asset_versions VALUES(aid,1,jsonb_build_object('id',aid,'workspaceId',r.workspace_id,'name',r.name,'category','reference','version',1,'archived',false,'synthetic',r.native_synthetic=1,'expiresAt',r.expires_at,'createdAt',at_time,'mediaType',mime,'size',(o->>'size')::bigint,'sha256',o->>'sha256','specs',s)::text,at_time);
 INSERT INTO studio_projects(id,tenant_id,workspace_id,name,purpose,document,environment,app_env,created_at,updated_at) VALUES(pid,r.tenant_id,r.workspace_id,r.name,'video',(v->'document')::text,'mock',r.app_env,at_time,at_time);INSERT INTO studio_project_versions VALUES(pid,1,r.name,(v->'document')::text,r.actor_id,at_time);
 INSERT INTO _dg_native_ae_media_receipts VALUES(r.id,token,i.input_hash,receipt_text,receipt_digest,at_time);UPDATE ae_media_adoptions SET status='succeeded',stage='finished',progress=100,asset_id=aid,project_id=pid,inspection_runtime=(v->'inspectionRuntime')::text,version=version+1,control_version=control_version+1,lease_token=NULL,lease_until=NULL,error_code=NULL,error_message=NULL,updated_at=at_time WHERE id=r.id;UPDATE ae_media_attempts SET status='succeeded',finished_at=at_time WHERE adoption_id=r.id AND attempt=r.attempts AND status='processing';INSERT INTO audit_events VALUES(gen_random_uuid()::text,r.tenant_id,r.workspace_id,r.actor_id,'studio.ae.media.completed',r.id,'confirmed',token,at_time);RETURN r.id;
END;$dg$;
DO $dg$ DECLARE f record;BEGIN FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace=current_schema()::regnamespace AND(proname LIKE 'dg_native_%ae_render%' OR proname LIKE 'dg_native_%ae_media%' OR proname='dg_native_ae_refresh_batch') LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC';END LOOP;END;$dg$;
